from pathlib import Path
root = Path('/tmp/aigunner/ai-gunner-dev10')

# Add reflective Gunner Arena shop integration.
p = root / 'src/main/java/ai/gunner/integration/GunnerArenaAdapter.java'
p.write_text('''package ai.gunner.integration;\n\nimport net.minecraft.client.player.LocalPlayer;\nimport net.minecraft.core.registries.BuiltInRegistries;\nimport net.minecraft.resources.ResourceLocation;\nimport net.minecraft.world.item.ItemStack;\n\nimport java.lang.reflect.Constructor;\nimport java.lang.reflect.Field;\nimport java.lang.reflect.Method;\n\n/** Optional integration with Gunner Arena. Everything is reflective so AI Gunner still loads without it. */\npublic final class GunnerArenaAdapter {\n    private static final String SECONDARY = "jeg:semi_auto_pistol";\n    private static final String PRIMARY = "jeg:custom_smg";\n    private static int buyCooldown;\n    private static int phase;\n\n    private GunnerArenaAdapter() {}\n\n    public static void tick() { if (buyCooldown > 0) buyCooldown--; }\n\n    public static boolean hasJegGun(LocalPlayer player) {\n        if (player == null) return false;\n        for (int i = 0; i < 9; i++) if (JegAdapter.isGun(player.getInventory().getItem(i))) return true;\n        return false;\n    }\n\n    public static boolean hasItem(LocalPlayer player, String id) {\n        if (player == null) return false;\n        ResourceLocation wanted = ResourceLocation.tryParse(id);\n        if (wanted == null) return false;\n        for (ItemStack stack : player.getInventory().items) {\n            if (!stack.isEmpty() && wanted.equals(BuiltInRegistries.ITEM.getKey(stack.getItem()))) return true;\n        }\n        return false;\n    }\n\n    /** Buy only missing baseline weapons. Server rejects the request if credits are insufficient. */\n    public static boolean ensureBaselineLoadout(LocalPlayer player) {\n        if (player == null || buyCooldown > 0) return false;\n        String wanted;\n        if (!hasItem(player, SECONDARY)) wanted = SECONDARY;\n        else if (!hasItem(player, PRIMARY)) wanted = PRIMARY;\n        else return false;\n        if (phase++ % 2 == 1 && !hasJegGun(player)) wanted = SECONDARY;\n        boolean sent = sendBuy(wanted);\n        buyCooldown = sent ? 80 : 120;\n        return sent;\n    }\n\n    private static boolean sendBuy(String weaponId) {\n        try {\n            Class<?> network = Class.forName("arena.forge.net.ArenaNetwork");\n            Field channelField = network.getField("CHANNEL");\n            Object channel = channelField.get(null);\n            if (channel == null) return false;\n            Class<?> request = Class.forName("arena.forge.net.ArenaNetwork$BuyRequest");\n            Constructor<?> ctor = request.getConstructor(String.class);\n            Object packet = ctor.newInstance(weaponId);\n            for (Method m : channel.getClass().getMethods()) {\n                if (m.getName().equals("sendToServer") && m.getParameterCount() == 1) {\n                    m.invoke(channel, packet);\n                    return true;\n                }\n            }\n        } catch (Throwable ignored) {}\n        return false;\n    }\n}\n''')

p = root / 'src/main/java/ai/gunner/brain/AIConfig.java'
s = p.read_text()
s = s.replace('public static final double AMMO_PICKUP_SEARCH_RANGE = 48.0;', 'public static final double AMMO_PICKUP_SEARCH_RANGE = 160.0;')
s = s.replace('public static final int RETURN_COMMAND_MAX_ATTEMPTS = 2;', 'public static final int RETURN_COMMAND_MAX_ATTEMPTS = 2;\\n    public static final int POST_RESPAWN_PLAY_DELAY_TICKS = 50;')
p.write_text(s)

p = root / 'src/main/java/ai/gunner/brain/CombatBrain.java'
s = p.read_text()
s = s.replace('import ai.gunner.integration.HealingAdapter;\\n', 'import ai.gunner.integration.HealingAdapter;\\nimport ai.gunner.integration.GunnerArenaAdapter;\\n')
s = s.replace('import net.minecraft.world.entity.item.ItemEntity;\\n', 'import net.minecraft.world.entity.Entity;\\nimport net.minecraft.world.entity.item.ItemEntity;\\n')
s = s.replace('    private ItemEntity ammoPickup;\\n', '    private Entity ammoTarget;\\n    private int postRespawnNoTargetTicks;\\n    private boolean needsPlayAfterRespawn;\\n')
s = s.replace('        ammoPickup = null;\\n', '        ammoTarget = null;\\n        postRespawnNoTargetTicks = 0;\\n        needsPlayAfterRespawn = false;\\n', 1)
s = s.replace('        if (ammoRefresh > 0) ammoRefresh--;\\n', '        if (ammoRefresh > 0) ammoRefresh--;\\n        GunnerArenaAdapter.tick();\\n')
s = s.replace('            state = BotState.RETURN_TO_GAME;\\n            deadTicks++;', '            state = BotState.RETURN_TO_GAME;\\n            needsPlayAfterRespawn = true;\\n            postRespawnNoTargetTicks = 0;\\n            deadTicks++;')
old = '''        if (target == null) {\n            state = BotState.SEARCH;\n            release(mc);\n            BaritoneAdapter.cancel();\n            pathTicks = 0;\n            lastPathGoal = null;\n            restoreSlot(self);\n            return;\n        }\n'''
new = '''        if (target == null) {\n            if (needsPlayAfterRespawn) {\n                postRespawnNoTargetTicks++;\n                if (postRespawnNoTargetTicks >= AIConfig.POST_RESPAWN_PLAY_DELAY_TICKS && returnRetry <= 0) {\n                    if (ReturnToGameAdapter.sendPlay(mc)) {\n                        returnRetry = AIConfig.RETURN_COMMAND_RETRY_TICKS;\n                        needsPlayAfterRespawn = false;\n                        postRespawnNoTargetTicks = 0;\n                    }\n                }\n            }\n\n            int idleGunSlot = WeaponSelector.chooseBestHotbarSlot(self, 16.0);\n            if (idleGunSlot >= 0 && idleGunSlot != self.getInventory().selected && !JegAdapter.isReloading()) {\n                self.getInventory().selected = idleGunSlot;\n            }\n            ItemStack idleGun = self.getMainHandItem();\n            if (!GunnerArenaAdapter.hasJegGun(self)) {\n                release(mc);\n                BaritoneAdapter.cancel();\n                GunnerArenaAdapter.ensureBaselineLoadout(self);\n                state = BotState.SEARCH;\n                return;\n            }\n            GunnerArenaAdapter.ensureBaselineLoadout(self);\n            if (JegAdapter.isGun(idleGun) && !JegAdapter.hasAmmo(idleGun) && JegAdapter.reserveAmmo(self, idleGun) <= 0\n                    && findAmmoDestination(mc, self, idleGun) != null) {\n                state = BotState.RESUPPLY;\n                resupply(mc, self, idleGun);\n                return;\n            }\n\n            state = BotState.SEARCH;\n            release(mc);\n            BaritoneAdapter.cancel();\n            pathTicks = 0;\n            lastPathGoal = null;\n            restoreSlot(self);\n            return;\n        } else {\n            needsPlayAfterRespawn = false;\n            postRespawnNoTargetTicks = 0;\n        }\n'''
if old not in s:
    raise RuntimeError('rc3 target-null anchor not found')
s = s.replace(old, new)
s = s.replace('&& findAmmoPickup(mc, self, gun) != null) state = BotState.RESUPPLY;', '&& findAmmoDestination(mc, self, gun) != null) state = BotState.RESUPPLY;')
start = s.index('    private ItemEntity findAmmoPickup(')
end = s.index('    private boolean shouldJump(', start)
replacement = '''    private Entity findAmmoDestination(Minecraft mc, LocalPlayer self, ItemStack gun) {\n        if (mc.level == null || self == null || !JegAdapter.isGun(gun)) return null;\n        if (ammoRefresh > 0 && ammoTarget != null && ammoTarget.isAlive()\n                && self.distanceTo(ammoTarget) <= AIConfig.AMMO_PICKUP_SEARCH_RANGE\n                && isAmmoDestinationForGun(gun, ammoTarget)) return ammoTarget;\n\n        ammoRefresh = AIConfig.AMMO_PICKUP_REFRESH_TICKS;\n        ItemEntity pickup = mc.level.getEntitiesOfClass(ItemEntity.class,\n                        self.getBoundingBox().inflate(AIConfig.AMMO_PICKUP_SEARCH_RANGE),\n                        e -> e.isAlive() && !e.getItem().isEmpty() && JegAdapter.isAmmoForGun(gun, e.getItem()))\n                .stream().min(Comparator.comparingDouble(self::distanceToSqr)).orElse(null);\n        if (pickup != null) {\n            ammoTarget = pickup;\n            return ammoTarget;\n        }\n\n        String exactTag = ammoSpawnerTag(gun);\n        Entity exact = mc.level.getEntities(null, self.getBoundingBox().inflate(AIConfig.AMMO_PICKUP_SEARCH_RANGE),\n                        e -> e.isAlive() && e.getTags().contains("item_spawner")\n                                && exactTag != null && e.getTags().contains(exactTag))\n                .stream().min(Comparator.comparingDouble(self::distanceToSqr)).orElse(null);\n        if (exact != null) {\n            ammoTarget = exact;\n            return ammoTarget;\n        }\n        ammoTarget = mc.level.getEntities(null, self.getBoundingBox().inflate(AIConfig.AMMO_PICKUP_SEARCH_RANGE),\n                        e -> e.isAlive() && e.getTags().contains("item_spawner")\n                                && e.getTags().contains("random_gun_ammo"))\n                .stream().min(Comparator.comparingDouble(self::distanceToSqr)).orElse(null);\n        return ammoTarget;\n    }\n\n    private boolean isAmmoDestinationForGun(ItemStack gun, Entity e) {\n        if (e instanceof ItemEntity item) return JegAdapter.isAmmoForGun(gun, item.getItem());\n        String exactTag = ammoSpawnerTag(gun);\n        return e.getTags().contains("item_spawner")\n                && ((exactTag != null && e.getTags().contains(exactTag)) || e.getTags().contains("random_gun_ammo"));\n    }\n\n    private String ammoSpawnerTag(ItemStack gun) {\n        var id = JegAdapter.ammoItemId(gun);\n        if (id == null) return null;\n        return switch (id.getPath()) {\n            case "pistol_ammo" -> "gun_1_ammo";\n            case "rifle_ammo" -> "gun_2_ammo";\n            case "shotgun_shell", "handmade_shell" -> "gun_3_ammo";\n            default -> null;\n        };\n    }\n\n    private void resupply(Minecraft mc, LocalPlayer self, ItemStack gun) {\n        HealingAdapter.stopUse(mc);\n        release(mc);\n        Entity destination = findAmmoDestination(mc, self, gun);\n        if (destination == null || !destination.isAlive()) {\n            BaritoneAdapter.cancel();\n            ammoTarget = null;\n            state = BotState.SEARCH;\n            return;\n        }\n        double d2 = self.distanceToSqr(destination);\n        BlockPos goal = destination.blockPosition();\n        double arrival = destination instanceof ItemEntity ? AIConfig.AMMO_PICKUP_ARRIVAL_DISTANCE_SQR : 1.8;\n        if (d2 <= arrival) {\n            BaritoneAdapter.cancel();\n            releaseCombat(mc);\n            ammoRefresh = 0;\n            return;\n        }\n        if (d2 <= 4.0) {\n            BaritoneAdapter.cancel();\n            moveToward(mc, self, goal, true);\n            return;\n        }\n        if (!BaritoneAdapter.pathTo(goal, ticks % AIConfig.AMMO_PICKUP_REFRESH_TICKS == 0)) {\n            moveToward(mc, self, goal, true);\n        }\n    }\n\n'''
s = s[:start] + replacement + s[end:]
s = s.replace('ammoPickup = null;', 'ammoTarget = null;')
p.write_text(s)

p = root / 'gradle.properties'
s = p.read_text()
if 'mod_version=1.5.0-rc2' not in s:
    raise RuntimeError('rc3 version anchor not found')
p.write_text(s.replace('mod_version=1.5.0-rc2', 'mod_version=1.5.0-rc3'))
(root / 'AI-GUNNER-1.5-RC3.md').write_text('''# AI Gunner 1.5 rc3\n\n- Gunner Arena test54 ammo-spawner awareness via entity scoreboard tags.\n- Resupply works even with no combat target.\n- Waits at exact pistol/rifle/shotgun spawner when ammo item is on cooldown.\n- Baseline shop integration through ArenaNetwork BuyRequest: JEG semi-auto pistol + custom SMG.\n- After death, if no target appears after respawn grace period, issues /play once.\n''')
print('rc3 patch applied')
